### Solution:
```swift
func convertDates(dates: [String], outputFormat: String) -> [String] {
    var convertedDates: [String] = []

    let dateFormatter = DateFormatter()
    dateFormatter.dateFormat = "yyyy-MM-dd"

    if let outputFormatter = DateFormatter.dateFormatterCache[outputFormat] {
        for dateStr in dates {
            if let date = dateFormatter.date(from: dateStr) {
                convertedDates.append(outputFormatter.string(from: date))
            } else {
                convertedDates.append("Invalid Date")
            }
        }
    } else {
        convertedDates.append("Invalid Output Format")
    }

    return convertedDates
}

extension DateFormatter {
    static var dateFormatterCache: [String: DateFormatter] = [:]

    static func dateFormatter(for format: String) -> DateFormatter {
        if let cachedFormatter = dateFormatterCache[format] {
            return cachedFormatter
        } else {
            let newFormatter = DateFormatter()
            newFormatter.dateFormat = format
            dateFormatterCache[format] = newFormatter
            return newFormatter
        }
    }
}
```

In the solution, the `convertDates` function takes the input dates and the desired output format as parameters. It initializes a `DateFormatter` object with the input date format "yyyy-MM-dd". It then checks if the output format has been previously cached in the `dateFormatterCache`. If the output format is found in the cache, it uses the cached `DateFormatter` to convert each date from the input format to the output format. If the output format is not found in the cache, it returns "Invalid Output Format". If any date in the input array is invalid, it returns "Invalid Date". The converted dates are then returned as an array of strings in the specified output format.

