```

### Solution:
```swift
func scrubSections(_ document: String, _ sections: [(Int, Int)]) -> String {
    var scrubbedDocument = document
    for (start, end) in sections {
        let startIndex = document.index(document.startIndex, offsetBy: start)
        let endIndex = document.index(document.startIndex, offsetBy: end)
        let range = startIndex...endIndex
        scrubbedDocument.removeSubrange(range)
    }
    return scrubbedDocument
}
```

