```

Assume that the manifest file will always follow the same format as shown in the code snippet.

### Solution:
```swift
func extractTargets(from manifest: String) -> [(name: String, dependencies: [String])] {
    var targets: [(name: String, dependencies: [String])] = []

    // Split the manifest by newlines and filter out empty lines
    let lines = manifest.components(separatedBy: .newlines).filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

    // Iterate through the lines to extract target information
    for line in lines {
        if line.contains(".target(name:") {
            if let targetName = line.components(separatedBy: "\"").dropFirst().first {
                let dependencies = line.components(separatedBy: "[").last?.components(separatedBy: "]").first?.components(separatedBy: ",").map { $0.trimmingCharacters(in: .whitespaces).replacingOccurrences(of: "\"", with: "") } ?? []
                targets.append((name: targetName, dependencies: dependencies))
            }
        }
    }

    return targets
}
```

This solution first splits the manifest into lines and filters out any empty lines. Then, it iterates through the lines to identify the target names and their dependencies, if any. The extracted target information is then added to the `targets` array, which is returned as the final result.

