```

Note:
- The transaction type will always be either "deposit" or "withdrawal".
- The transaction amount will be a positive number for deposits and a negative number for withdrawals.
- The balance should be calculated by summing all the transaction amounts.

### Solution:
```swift
func calculateBalance(transactions: [(type: String, amount: Double)]) -> Double {
    var balance: Double = 0.0
    for transaction in transactions {
        if transaction.type == "deposit" {
            balance += transaction.amount
        } else if transaction.type == "withdrawal" {
            balance -= transaction.amount
        }
    }
    return balance
}
