func extractColorList(from htmlString: String) -> [(String, String)] {
    var colorList = [(String, String)]()
    let regexString = "<font color=\\\"#+([.0-9a-zA-z]+)\\\">(.*?)</font>"

    do {
        let regex = try NSRegularExpression(pattern: regexString, options: [])
        let matches = regex.matches(in: htmlString, options: [], range: NSRange(location: 0, length: htmlString.utf16.count))

        for match in matches {
            if let range = Range(match.range(at: 1), in: htmlString),
               let colorRange = Range(match.range(at: 2), in: htmlString) {
                let color = String(htmlString[range])
                let content = String(htmlString[colorRange])
                colorList.append((color, content))
            }
        }
    } catch {
        print("Error creating regex: \(error)")
    }

    return colorList
}

