### Solution:
```php
private function getProductsForAttach($carts, $method, $cashier_id, $uuid)
{
    $items = [];
    foreach ($carts as $cart) {
        foreach ($cart as $product) {
            $product['cashier_id'] = $cashier_id;
            $product['uuid'] = $uuid;
            $items[] = $product;
        }
    }

    if ($method === "separate") {
        $separateItems = [];
        foreach ($carts as $index => $cart) {
            $separateItems[$index] = [];
            foreach ($cart as $product) {
                $product['cashier_id'] = $cashier_id;
                $product['uuid'] = $uuid;
                $separateItems[$index][] = $product;
            }
        }
        return $separateItems;
    }

    return $items;
}
```

