    assert_eq!(stack.pop(), Some(15));
    assert_eq!(stack.pop(), Some(10));
    assert_eq!(stack.is_empty(), false);
    assert_eq!(stack.pop(), Some(5));
    assert_eq!(stack.is_empty(), true);
}
