### Solution:
```rust
use std::collections::HashSet;
use std::fs;
use std::path::Path;

fn find_unique_file_extensions(directory_path: &str) -> HashSet<String> {
    let mut extensions = HashSet::new();
    if let Ok(entries) = fs::read_dir(directory_path) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_file() {
                    if let Some(ext) = path.extension() {
                        if let Some(ext_str) = ext.to_str() {
                            extensions.insert(ext_str.to_lowercase());
                        }
                    }
                } else if path.is_dir() {
                    extensions.extend(find_unique_file_extensions(&path.to_string_lossy()));
                }
            }
        }
    }
    extensions
}

fn main() {
    let directory_path = "path_to_directory"; // Replace with the actual directory path
    let unique_extensions = find_unique_file_extensions(directory_path);
    println!("Unique file extensions: {:?}", unique_extensions);
}
```

This solution uses a recursive approach to traverse the directory structure, adding unique file extensions to a `HashSet`. It checks if each entry is a file and extracts its extension, adding it to the set. If the entry is a directory, the function recursively calls itself to process the subdirectory. Finally, it returns the set of unique file extensions found within the directory and its subdirectories.

