```swift
func parseLicense(license: String) -> (permissions: [String], conditions: String, liability: String) {
    var permissions: [String] = []
    var conditions: String = ""
    var liability: String = ""

    if let permissionRange = license.range(of: "to permit persons to whom the Software is furnished to do so, subject to the following conditions:") {
        let permissionSubstring = license[..<permissionRange.lowerBound]
        let permissionComponents = permissionSubstring.components(separatedBy: "rights to ")
        if permissionComponents.count > 1 {
            let permissionList = permissionComponents[1].components(separatedBy: ", ")
            permissions = permissionList
        }
    }

    if let conditionsRange = license.range(of: "conditions:\n//") {
        let conditionsSubstring = license[conditionsRange.upperBound...]
        if let liabilityRange = conditionsSubstring.range(of: "THE SOFTWARE IS PROVIDED") {
            conditions = String(conditionsSubstring[..<liabilityRange.lowerBound])
            liability = String(conditionsSubstring[liabilityRange.lowerBound...])
        }
    }

    return (permissions, conditions, liability)
}

