struct Section {
    var title: String
    var options: [String]
}

var models: [Section] = []

func configure() {
    // Add a new section with a given title and an empty list of options
    func addSection(title: String) {
        let newSection = Section(title: title, options: [])
        models.append(newSection)
    }

    // Add a new option to a specified section
    func addOption(to sectionIndex: Int, option: String) {
        guard sectionIndex >= 0, sectionIndex < models.count else {
            return
        }
        models[sectionIndex].options.append(option)
    }

    // Remove a section and all its associated options
    func removeSection(at index: Int) {
        guard index >= 0, index < models.count else {
            return
        }
        models.remove(at: index)
    }

    // Remove a specific option from a given section
    func removeOption(from sectionIndex: Int, at optionIndex: Int) {
        guard sectionIndex >= 0, sectionIndex < models.count else {
            return
        }
        guard optionIndex >= 0, optionIndex < models[sectionIndex].options.count else {
            return
        }
        models[sectionIndex].options.remove(at: optionIndex)
    }

