    place1: Place { consumed_by: vec![transition1, transition2], produced_by: vec![transition3] },
    place2: Place { consumed_by: vec![transition1, transition2], produced_by: vec![transition3] },
    place3: Place { consumed_by: vec![transition1], produced_by: vec![transition3, transition4] },
    place4: Place { consumed_by: vec![transition1], produced_by: vec![transition3, transition4] },
}
```
