use std::collections::HashMap;

#[derive(Debug, PartialEq, Eq, Hash, Clone)]
struct Place {
    consumed_by: Vec<TransitionId>,
    produced_by: Vec<TransitionId>,
}

type PlaceId = String;
type TransitionId = String;

fn find_similar_places(net: &HashMap<PlaceId, Place>) -> Vec<(PlaceId, PlaceId)> {
    let mut similar_places = Vec::new();

    for (pl_1, place_1) in net.iter() {
        for (pl_2, place_2) in net.iter() {
            if pl_1 != pl_2
                && place_1.consumed_by.len() == place_2.consumed_by.len()
                && place_1.produced_by.len() == place_2.produced_by.len()
                && place_1
                    .produced_by
                    .iter()
                    .zip(&place_2.produced_by)
                    .all(|(w_1, w_2)| w_1 == w_2)
            {
                similar_places.push((pl_1.clone(), pl_2.clone()));
            }
        }
    }

    similar_places
}

