use std::collections::HashSet;

pub struct FeatureGate {
    enabled_modules: HashSet<String>,
}

impl FeatureGate {
    pub fn new() -> Self {
        FeatureGate {
            enabled_modules: HashSet::new(),
        }
    }

    pub fn enable_module(&mut self, module_name: &str, enable: bool) {
        if enable {
            self.enabled_modules.insert(module_name.to_string());
        } else {
            self.enabled_modules.remove(module_name);
        }
    }

    pub fn is_module_enabled(&self, module_name: &str) -> bool {
        self.enabled_modules.contains(module_name)
    }

    pub fn list_enabled_modules(&self) -> Vec<String> {
        self.enabled_modules.iter().cloned().collect()
    }
}

