    feature_gate.enable_module("hashing_utils", true);
    feature_gate.enable_module("serde_utils", false);

    assert_eq!(feature_gate.is_module_enabled("hashing_utils"), true);
    assert_eq!(feature_gate.is_module_enabled("serde_utils"), false);

