```

### Solution:
```swift
enum Setting {
    case value(Bool?)
    case value(String?)
    case undefined
}

func generateReport(settings: [Setting]) -> [String] {
    var report: [String] = []
    for setting in settings {
        switch setting {
        case .value(let allowPartialAddresses):
