        'controller' => 'ClientController',
        'controllerMethod' => 'add'
    ],
    [
        'method' => 'GET',
        'path' => 'user/profile',
        'controller' => 'UserController',
        'controllerMethod' => 'profile'
    ],
    [
        'method' => 'PUT',
        'path' => 'post/update',
        'controller' => 'PostController',
        'controllerMethod' => 'update'
    ]
]
```
