use chrono::{DateTime, Utc};
use sha2::{Digest, Sha256};
use ethereum_types::H256;

pub type BlockHeight = u64;
pub type BlockTxList = Vec<Transaction>;

pub struct Transaction {
    // transaction fields
}

pub fn block_header_to_digest(
    height: BlockHeight,
    prev_blk_hash: H256,
    time_stamp: DateTime<Utc>,
) -> H256 {
    let mut input_bytes = Vec::new();
    input_bytes.extend_from_slice(&height.to_be_bytes());
    input_bytes.extend_from_slice(&prev_blk_hash);
    input_bytes.extend_from_slice(time_stamp.timestamp().to_be_bytes());

    let mut hasher = Sha256::new();
    hasher.update(&input_bytes);
    let result = hasher.finalize();

    H256::from_slice(&result)
}
```

