pub type EntityID = u32;
pub type ComponentList<T> = Vec<(EntityID, T)>;

impl<T> ComponentList<T> {
    pub fn add_component(&mut self, entity_id: EntityID, component: T) {
        // Add the component to the ComponentList for the given entity_id
        self.retain(|&(id, _)| id != entity_id);
        self.push((entity_id, component));
    }

    pub fn get_components(&self, entity_id: EntityID) -> Vec<&T> {
        // Retrieve all components for the given entity_id
        self.iter()
            .filter(|&&(id, _)| id == entity_id)
            .map(|&(_, ref component)| component)
            .collect()
    }
}

