mod merkle_operations {
    use tree_storage::abc::*;
    use merkle_tree::abc::*;

    pub fn calculate_merkle_hash(data: &[&str]) -> Result<String, String> {
        // Create a new tree for storing the data
        let mut tree = Tree::new();

        // Store the data items in the tree
        for item in data {
