### Solution:
```swift
func uniqueCityNames(from cities: [CityTourInfoOptionData]) -> [String] {
    var uniqueNames: [String] = []
    var seenNames: Set<String> = Set()

    for city in cities {
        if !seenNames.contains(city.name) {
            uniqueNames.append(city.name)
            seenNames.insert(city.name)
        }
    }

    return uniqueNames
}
