function isHTMLValid(html) {
  const stack = [];
  const openingTag = '<div>';
  const closingTag = '</div>';

  for (let i = 0; i < html.length; i++) {
    if (html.substring(i, i + openingTag.length) === openingTag) {
      stack.push(openingTag);
    } else if (html.substring(i, i + closingTag.length) === closingTag) {
      if (stack.length === 0) {
        return false; // Closing tag without matching opening tag
      } else {
        stack.pop();
      }
    }
  }

  return stack.length === 0; // All opening tags have matching closing tags
