- The high score achieved by the players.

For example, given the input `(9, 25)`, the function should return `32`.

### Solution:
```rust
fn marble_highscore(game: &(usize, usize)) -> usize {
    let (players, last_marble) = *game;
    let mut circle = vec![0];
    let mut scores = vec![0; players];
    let mut current_player = 0;
    let mut current_marble = 0;

    for marble in 1..=last_marble {
        if marble % 23 == 0 {
            current_marble = (current_marble + circle.len() - 7) % circle.len();
            scores[current_player] += marble + circle.remove(current_marble);
        } else {
            current_marble = (current_marble + 2) % circle.len();
            if current_marble == 0 {
