### Solution:
```php
<?php
// Read the contents of the file into an array
$fileContents = file('image-display-archive.php', FILE_IGNORE_NEW_LINES);

// Initialize variables for calculations
$totalArchives = 0;
$maxStars = 0;
$archiveWithMaxStars = '';
$specifiedRangeArchives = [];

// Iterate through each line in the file
foreach ($fileContents as $line) {
    // Extract filename and GitHub stars range from the line
    preg_match('/<filename>(.*?)<gh_stars>(\d+)-(\d+)/', $line, $matches);
    $filename = $matches[1];
    $starsLowerBound = intval($matches[2]);
    $starsUpperBound = intval($matches[3]);

    // Increment total number of archives
    $totalArchives++;

    // Update maximum stars and corresponding archive
    if ($starsUpperBound > $maxStars) {
        $maxStars = $starsUpperBound;
        $archiveWithMaxStars = $filename;
    }

    // Check if the stars fall within the specified range (e.g., 500-1000)
    if ($starsLowerBound >= 500 && $starsUpperBound <= 1000) {
        $specifiedRangeArchives[] = $filename;
    }
}

// Output the results
