  let angle = Math.atan2(event.clientY - player.y, event.clientX - player.x);
  let velocity = {
    x: Math.cos(angle),
    y: Math.sin(angle)
  };
  projectiles.push({ x: player.x, y: player.y, velocity });
});

// Function to update game state and draw elements
