func calculateBalance(transactions: [(String, Int)]) -> Int {
    var balance = 0
    for transaction in transactions {
        let (type, amount) = transaction
        if type == "deposit" {
            balance += amount
        } else if type == "withdrawal" {
            if balance - amount >= 0 {
                balance -= amount
            }
        }
    }
    return balance
}

