def convert_digit(num):
    digits = ["Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"]
    return digits[num]

def convert_tens(num):
    tens = ["Zero", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]
    return tens[num // 10]

def convert_less_than_100(num):
    if num < 10:
        return convert_digit(num)
    elif num < 20:
        tens = ["Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
        return tens[num % 10]
    else:
        return convert_tens(num) + (" " + convert_digit(num % 10) if num % 10 else "")

def convert_less_than_1000(num):
    hundreds = num // 100
    if hundreds:
        return convert_digit(hundreds) + " Hundred" + ("" if num % 100 == 0 else " and " + convert_less_than_100(num % 100))
    else:
        return convert_less_than_100(num)

def convert_less_than_10000(num):
    thousands = num // 1000
    if thousands:
        return convert_less_than_100(thousands) + " Thousand" + ("" if num % 1000 == 0 else " and " + convert_less_than_1000(num % 1000))
